import React from 'react';
import { Button } from '../ui/Button';
import { Menu } from 'lucide-react';

export default function Header() {
  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-black/80 backdrop-blur-md border-b border-gray-600">
      <div className="container mx-auto px-6 lg:px-16 py-4 flex items-center justify-between max-w-7xl">
        <div className="text-lg font-bold text-white">BADR EDDINE DIYAF</div>
        <Button variant="outline" size="sm" className="rounded-full bg-transparent border-teal-500 text-teal-500 hover:bg-teal-500/20 hover:text-white">
          Menu
          <Menu className="ml-2 h-4 w-4" />
        </Button>
      </div>
    </header>
  );
}
